// Regenerate src/java_grapheme_data.rs with OpenJDK 25.0.2:
// java --add-opens java.base/jdk.internal.util.regex=ALL-UNNAMED generate_java_graphemes.java
// The table records the grapheme properties observed in the reference runtime.
import java.lang.reflect.Method;

class GenerateJavaGraphemes {
    private static final String[] BREAK_TYPES = {
        "Other", "Cr", "Lf", "Control", "Extend", "Zwj", "Regional", "Prepend",
        "SpacingMark", "L", "V", "T", "Lv", "Lvt", "Pictographic"
    };

    private static Method method(String owner, String name) throws Exception {
        var method = Class.forName("jdk.internal.util.regex." + owner)
            .getDeclaredMethod(name, int.class);
        method.setAccessible(true);
        return method;
    }

    private static int properties(
        int code, Method type, Method consonant, Method linker, Method extend
    ) throws Exception {
        if (!Character.isValidCodePoint(code) || code >= 0xD800 && code <= 0xDFFF ||
            code >= 0xAC00 && code <= 0xD7A3) {
            return 0;
        }
        int indic = (boolean) consonant.invoke(null, code) ? 1
            : (boolean) linker.invoke(null, code) ? 2 : (boolean) extend.invoke(null, code) ? 3 : 0;
        return (int) type.invoke(null, code) | (indic << 4);
    }

    public static void main(String[] args) throws Exception {
        if (!Runtime.version().version().equals(java.util.List.of(25, 0, 2))) {
            throw new IllegalArgumentException("Regeneration requires OpenJDK 25.0.2");
        }
        var type = method("Grapheme", "getType");
        var consonant = method("IndicConjunctBreak", "isConsonant");
        var linker = method("IndicConjunctBreak", "isLinker");
        var extend = method("IndicConjunctBreak", "isExtend");
        String[] indicTypes = {"None", "Consonant", "Linker", "Extend"};
        System.out.println("// Generated by generate_java_graphemes.java.");
        System.out.println("// See ../LICENSE-UNICODE for the underlying Unicode data.");
        System.out.println();
        System.out.println("use super::java_grapheme::{Indic, Kind};");
        System.out.println();
        System.out.println("#[rustfmt::skip]");
        System.out.println("pub(super) const RANGES: &[(u32, u32, Kind, Indic)] = &[");
        int start = 0;
        int previous = 0;
        for (int code = 0; code <= 0x110000; code++) {
            int next = properties(code, type, consonant, linker, extend);
            if (next == previous) continue;
            if (previous != 0) {
                System.out.printf("    (0x%X, 0x%X, Kind::%s, Indic::%s),%n",
                    start, code - 1, BREAK_TYPES[previous & 0xf], indicTypes[previous >>> 4]);
            }
            start = code;
            previous = next;
        }
        System.out.println("];");
    }
}
